def gen(rng):
    LIM = 5000

    def make_tree(n, mode):
        par = [-1] * n
        dep = [0] * n
        ok = [0]
        for i in range(1, n):
            if mode == 'chain' and dep[i - 1] < LIM:
                p = i - 1
            elif mode == 'star':
                p = 0
            elif mode == 'heap':
                p = (i - 1) // 2
            else:
                p = ok[rng.randrange(len(ok))]
            par[i] = p
            dep[i] = dep[p] + 1
            if dep[i] < LIM:
                ok.append(i)
        perm = list(range(1, n))
        rng.shuffle(perm)
        perm = [0] + perm
        edges = []
        for i in range(1, n):
            a, b = perm[par[i]], perm[i]
            if rng.random() < 0.5:
                a, b = b, a
            edges.append((a, b))
        rng.shuffle(edges)
        return edges

    def case(n, q, mode, a_r, x_r):
        edges = make_tree(n, mode)
        a = [rng.randint(-a_r, a_r) for _ in range(n)]
        lines = [str(n), ' '.join(map(str, a))]
        lines += ['%d %d' % e for e in edges]
        lines.append(str(q))
        for _ in range(q):
            lines.append('%d %d %d' % (rng.randrange(n), rng.randrange(n), rng.randint(-x_r, x_r)))
        return '\n'.join(lines)

    tests = []
    tests.append('1\n5\n1\n0 0 3')
    tests.append('1\n0\n2\n0 0 4\n0 0 -4')
    tests.append('2\n1 2\n0 1\n3\n0 1 5\n1 0 -5\n1 1 2')
    tests.append('3\n0 0 0\n0 1\n0 2\n2\n1 2 7\n2 1 -7')
    for n in (2, 3, 4, 5, 6, 8, 10, 12):
        for mode in ('rand', 'chain', 'star', 'heap'):
            if rng.random() < 0.6:
                tests.append(case(n, rng.randint(1, 8), mode, 50, rng.choice((3, 9))))
    for n in (3000, 3000):
        for mode in ('rand', 'chain', 'heap'):
            tests.append(case(n, 3000, mode, 10**6, 10**4))
    tests.append(case(50000, 50000, 'rand', 10**6, 10**4))
    tests.append(case(50000, 50000, 'chain', 10**6, 10**4))
    tests.append(case(50000, 50000, 'star', 10**6, 10**4))
    return tests
